          "title": "Id",
          "type": "string"
        },
        "explanation": {
          "minLength": 1,
          "pattern": "[^\\u0009-\\u000D\\u0020\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF]",
          "title": "Explanation",
          "type": "string"
        },
        "evidenceIds": {
          "items": {
            "minLength": 1,
            "pattern": "[^\\u0009-\\u000D\\u0020\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF]",
            "type": "string"
          },
          "minItems": 1,
          "title": "Evidenceids",
          "type": "array",
          "uniqueItems": true
        }
      },
      "required": [
        "id",
        "explanation",
        "evidenceIds"
      ],
      "title": "Alternative",
      "type": "object"
    },
    "Finding": {
      "additionalProperties": false,
      "properties": {
        "id": {
          "minLength": 1,
          "pattern": "[^\\u0009-\\u000D\\u0020\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF]",
          "title": "Id",
          "type": "string"
        },
        "claim": {
          "minLength": 1,
          "pattern": "[^\\u0009-\\u000D\\u0020\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF]",
          "title": "Claim",
          "type": "string"
        },
        "evidenceIds": {
          "items": {
            "minLength": 1,
            "pattern": "[^\\u0009-\\u000D\\u0020\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF]",
            "type": "string"
          },
          "minItems": 1,
          "title": "Evidenceids",
          "type": "array",
          "uniqueItems": true
        },
        "confidence": {
          "enum": [
            "low",
            "medium",
            "high"
          ],
          "title": "Confidence",
          "type": "string"
        }
      },
      "required": [
        "id",
        "claim",
        "evidenceIds",
        "confidence"
      ],
      "title": "Finding",
      "type": "object"
    }
  },
  "additionalProperties": false,
  "properties": {
    "version": {
      "const": "wememo-interaction-reasoning-v1",
      "title": "Version",
      "type": "string"
    },
    "summary": {
      "minLength": 1,
      "pattern": "[^\\u0009-\\u000D\\u0020\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF]",
      "title": "Summary",
      "type": "string"
    },
    "findings": {
      "items": {
        "$ref": "#/$defs/Finding"
      },
      "title": "Findings",
      "type": "array"
    },
    "alternativeExplanations": {
      "items": {
        "$ref": "#/$defs/Alternative"
      },
      "title": "Alternativeexplanations",
      "type": "array"
    },
    "uncertainties": {
      "items": {
        "minLength": 1,
        "pattern": "[^\\u0009-\\u000D\\u0020\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF]",
        "type": "string"
      },
      "minItems": 1,
      "title": "Uncertainties",
      "type": "array"
    }
  },
  "required": [
    "version",
    "summary",
    "findings",
    "alternativeExplanations",
    "uncertainties"
  ],
  "title": "RelationshipAnalysis",
  "type": "object"
}

